def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    if rows == 0 or cols == 0:
        return grid

    # Find background color (the non-8 color)
    background = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 8:
                if background is None:
                    background = grid[r][c]

    if background is None:
        return grid

    # Flood fill from edges to find exterior background
    seen = set()
    queue = []
    head = 0

    # Add all edge background pixels
    for r in range(rows):
        for c in range(cols):
            if (r == 0 or r == rows - 1 or c == 0 or c == cols - 1) and grid[r][c] == background:
                seen.add((r, c))
                queue.append((r, c))

    # Flood fill
    while head < len(queue):
        r, c = queue[head]
        head += 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == background and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    queue.append((nr, nc))

    # Fill enclosed regions with 2
    result = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background and (r, c) not in seen:
                result[r][c] = 2

    return result
